#!/usr/bin/env python3
"""Alert on recent AAP2 job failures per controller."""

WINDOW_MINUTES = 60
WARN_FAILURES = 2
CRIT_FAILURES = 4
IGNORE_ACTIONS = ("destroy",)

def classify(failures):
    if failures >= CRIT_FAILURES:
        return 2
    if failures >= WARN_FAILURES:
        return 1
    return 0

